def list_all_allergy_records(self) -> dict:
    """
    Return every allergy record stored in the system across all patients.

    Returns:
        dict: On success, {
            "success": True,
            "data": List[AllergyRecord]
        } containing all allergy records currently stored.
        On failure, {
            "success": False,
            "error": str
        }.

    Constraints:
        - Includes all allergy records regardless of patient or status.
        - Must preserve audit-related fields as stored.
    """
    try:
        return {
            "success": True,
            "data": list(self.allergy_records.values())
        }
    except Exception:
        return {
            "success": False,
            "error": "Unable to list allergy records"
        }

def list_allergy_records_by_patient(self, patient_id: str) -> dict:
    """
    Return all allergy records for a specific patient.

    Args:
        patient_id (str): The identifier of the patient whose allergy records
            should be retrieved.

    Returns:
        dict: On success, returns {
            "success": True,
            "data": List[AllergyRecord]
        } where the list may be empty if the patient has no allergy records.
        On failure, returns {
            "success": False,
            "error": str
        }.

    Constraints:
        - The patient_id must exist in the system.
        - This operation is read-only and does not modify EHR state.
        - Multiple allergy records may exist for the same patient.
    """
    if patient_id not in self.patients:
        return {"success": False, "error": "Patient not found"}

    records = [
        record
        for record in self.allergy_records.values()
        if record["patient_id"] == patient_id
    ]

    return {"success": True, "data": records}

def get_allergy_record_by_id(self, allergy_id: str) -> dict:
    """
    Retrieve a single allergy record by allergy_id.

    Args:
        allergy_id (str): The unique identifier of the allergy record.

    Returns:
        dict: On success, {
            "success": True,
            "data": AllergyRecord
        }.
        On failure, {
            "success": False,
            "error": str
        }.

    Constraints:
        - The allergy_id must refer to an existing allergy record.
        - This is a read-only operation and must not modify system state.
        - Audit fields such as recorded_at and recorded_by are returned as stored.
    """
    if not isinstance(allergy_id, str) or not allergy_id.strip():
        return {"success": False, "error": "Invalid allergy_id"}

    record = self.allergy_records.get(allergy_id)
    if record is None:
        return {"success": False, "error": "Allergy record not found"}

    return {"success": True, "data": record}

def filter_allergy_records_by_status(self, status: str) -> dict:
    """
    Return allergy records matching a given status.

    Args:
        status (str): Status to filter by, such as 'active', 'inactive', or 'resolved'.

    Returns:
        dict: On success, {"success": True, "data": List[AllergyRecord]}.
              On failure, {"success": False, "error": str}.

    Constraints:
        - Filters across all patients system-wide.
        - Matching is performed against the AllergyRecord.status field.
        - An empty match set is a successful response with an empty list.
    """
    if not isinstance(status, str) or not status.strip():
        return {"success": False, "error": "Status must be a non-empty string"}

    normalized_status = status.strip().lower()
    matching_records = [
        record
        for record in self.allergy_records.values()
        if isinstance(record.get("status"), str)
        and record["status"].strip().lower() == normalized_status
    ]

    return {"success": True, "data": matching_records}

def search_allergy_records_by_allergen(self, keyword: str) -> dict:
    """
    Find allergy records whose allergen field matches the given allergen name or keyword.

    Args:
        keyword (str): Search text to match against the allergen name.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": List[AllergyRecord]
            }
            where the list contains all matching allergy records.
            If no records match, the list is empty.

        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - Search is performed system-wide across all allergy records.
        - Matching should be case-insensitive.
        - The search keyword must be a non-empty string.
        - This operation does not modify system state.
    """
    if not isinstance(keyword, str) or not keyword.strip():
        return {"success": False, "error": "Search keyword must be a non-empty string"}

    normalized_keyword = keyword.strip().lower()
    matches = [
        allergy_record
        for allergy_record in self.allergy_records.values()
        if normalized_keyword in allergy_record.get("allergen", "").lower()
    ]

    return {"success": True, "data": matches}

def get_patient_by_id(self, patient_id: str) -> dict:
    """
    Retrieve a patient record by patient identifier.

    Args:
        patient_id (str): The unique identifier of the patient to retrieve.

    Returns:
        dict: On success, {
            "success": True,
            "data": PatientRecord
        }.
        On failure, {
            "success": False,
            "error": str
        }.

    Constraints:
        - The patient_id must be provided and non-empty.
        - The patient must exist in the EHR system.
        - This is a read-only query and does not modify state.
    """
    if not isinstance(patient_id, str) or not patient_id.strip():
        return {"success": False, "error": "Invalid patient_id"}

    patient = self.patients.get(patient_id)
    if patient is None:
        return {"success": False, "error": "Patient not found"}

    return {"success": True, "data": patient}

def get_clinician_by_id(self, user_id: str) -> dict:
    """
    Retrieve a clinician user record by user_id for audit and authorship context.

    Args:
        user_id (str): The unique identifier of the clinician user to retrieve.

    Returns:
        dict: On success, {"success": True, "data": ClinicianUserRecord}.
              On failure, {"success": False, "error": <reason>}.

    Constraints:
        - The clinician user must exist in self.clinician_users.
        - This operation is read-only and does not modify system state.
    """
    if not user_id:
        return {"success": False, "error": "Invalid user_id"}

    clinician = self.clinician_users.get(user_id)
    if clinician is None:
        return {"success": False, "error": "Clinician user not found"}

    return {"success": True, "data": clinician}

def list_encounters_by_patient(self, patient_id: str) -> dict:
    """
    Return all encounter records associated with a given patient.

    Args:
        patient_id (str): The unique identifier of the patient whose encounters
            should be retrieved.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": [EncounterRecord, ...]
            }
            On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The patient must exist in self.patients.
        - Encounters are returned only when their patient_id matches the input.
        - Returns an empty list if the patient exists but has no encounters.
    """
    if not isinstance(patient_id, str) or not patient_id.strip():
        return {"success": False, "error": "Invalid patient_id"}

    if patient_id not in self.patients:
        return {"success": False, "error": "Patient not found"}

    encounters = [
        encounter
        for encounter in self.encounters.values()
        if encounter["patient_id"] == patient_id
    ]

    return {"success": True, "data": encounters}

def list_verified_allergy_records(self, verification_status: str) -> dict:
    """
    Return all allergy records that match the specified verification status.

    Args:
        verification_status (str): The verification status to filter by
            (for example: "verified", "unverified", or "pending").

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": List[AllergyRecord]
            }
        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - Performs a system-wide search across all allergy records.
        - Matching is exact on the `verification_status` field.
        - Does not modify any stored records.
    """
    if not isinstance(verification_status, str) or not verification_status.strip():
        return {"success": False, "error": "verification_status must be a non-empty string"}

    matches = [
        record
        for record in self.allergy_records.values()
        if record.get("verification_status") == verification_status
    ]

    return {"success": True, "data": matches}

def create_allergy_record(self, allergy_record: dict) -> dict:
    """
    Add a new allergy record to the system.

    Args:
        allergy_record (dict): A dictionary containing the allergy record data.
            Required keys:
            - allergy_id
            - patient_id
            - allergen
            - reaction
            - severity
            - status
            - recorded_at
            - recorded_by
            - verification_status

    Returns:
        dict: On success, returns:
            {"success": True, "message": "Allergy record created successfully"}
        On failure, returns:
            {"success": False, "error": "<reason>"}

    Constraints:
        - allergy_id must be unique.
        - patient_id must reference an existing patient.
        - recorded_at, recorded_by, and verification_status are preserved as provided.
        - The method does not raise exceptions; invalid input is reported via the returned dict.
    """
    if not isinstance(allergy_record, dict):
        return {"success": False, "error": "Invalid allergy record payload"}

    required_fields = {
        "allergy_id",
        "patient_id",
        "allergen",
        "reaction",
        "severity",
        "status",
        "recorded_at",
        "recorded_by",
        "verification_status",
    }

    missing_fields = [field for field in required_fields if field not in allergy_record]
    if missing_fields:
        return {
            "success": False,
            "error": f"Missing required fields: {', '.join(sorted(missing_fields))}",
        }

    allergy_id = allergy_record.get("allergy_id")
    patient_id = allergy_record.get("patient_id")

    if not isinstance(allergy_id, str) or not allergy_id.strip():
        return {"success": False, "error": "Invalid allergy_id"}
    if not isinstance(patient_id, str) or not patient_id.strip():
        return {"success": False, "error": "Invalid patient_id"}

    if allergy_id in self.allergy_records:
        return {"success": False, "error": "Allergy record already exists"}

    if patient_id not in self.patients:
        return {"success": False, "error": "Patient does not exist"}

    self.allergy_records[allergy_id] = allergy_record  # preserve audit fields as provided
    return {"success": True, "message": "Allergy record created successfully"}

def update_allergy_record(
    self,
    allergy_id: str,
    allergen: str = None,
    reaction: str = None,
    severity: str = None,
    verification_status: str = None
) -> dict:
    """
    Modify mutable fields of an existing allergy record.

    Args:
        allergy_id (str): Identifier of the allergy record to update.
        allergen (str, optional): New allergen value.
        reaction (str, optional): New reaction value.
        severity (str, optional): New severity value.
        verification_status (str, optional): New verification status value.

    Returns:
        dict: On success, returns:
            {"success": True, "message": "..."}
        On failure, returns:
            {"success": False, "error": "<reason>"}

    Constraints:
        - The allergy record must exist.
        - Only mutable clinical fields may be updated.
        - Immutable audit/linkage fields such as allergy_id, patient_id, recorded_at, and recorded_by are preserved.
        - At least one mutable field must be provided.
    """
    if allergy_id not in self.allergy_records:
        return {"success": False, "error": "Allergy record not found"}

    updates = {}
    if allergen is not None:
        if not isinstance(allergen, str) or not allergen.strip():
            return {"success": False, "error": "Invalid allergen value"}
        updates["allergen"] = allergen

    if reaction is not None:
        if not isinstance(reaction, str):
            return {"success": False, "error": "Invalid reaction value"}
        updates["reaction"] = reaction

    if severity is not None:
        if not isinstance(severity, str) or not severity.strip():
            return {"success": False, "error": "Invalid severity value"}
        updates["severity"] = severity

    if verification_status is not None:
        if not isinstance(verification_status, str) or not verification_status.strip():
            return {"success": False, "error": "Invalid verification_status value"}
        updates["verification_status"] = verification_status

    if not updates:
        return {"success": False, "error": "No mutable fields provided for update"}

    record = self.allergy_records[allergy_id].copy()
    record.update(updates)
    self.allergy_records[allergy_id] = record

    return {"success": True, "message": f"Allergy record {allergy_id} updated successfully"}

def update_allergy_status(self, allergy_id: str, status: str) -> dict:
    """
    Update the status of an existing allergy record.

    Args:
        allergy_id (str): The unique identifier of the allergy record to update.
        status (str): The new status for the allergy record. Must be one of
            {"active", "inactive", "resolved"}.

    Returns:
        dict: On success, returns:
            {"success": True, "message": "..."}
        On failure, returns:
            {"success": False, "error": "..."}.

    Constraints:
        - The allergy record must exist.
        - The status must be one of: active, inactive, resolved.
        - This operation updates only the status field and preserves audit fields.
    """
    allowed_statuses = {"active", "inactive", "resolved"}

    if not isinstance(allergy_id, str) or not allergy_id.strip():
        return {"success": False, "error": "Invalid allergy_id"}

    if not isinstance(status, str) or not status.strip():
        return {"success": False, "error": "Invalid status"}

    normalized_status = status.strip().lower()
    if normalized_status not in allowed_statuses:
        return {
            "success": False,
            "error": "Invalid status; must be one of active, inactive, resolved"
        }

    record = self.allergy_records.get(allergy_id)
    if record is None:
        return {"success": False, "error": "Allergy record not found"}

    record["status"] = normalized_status
    self.allergy_records[allergy_id] = record

    return {
        "success": True,
        "message": f"Allergy record {allergy_id} status updated to {normalized_status}"
    }

def resolve_allergy_record(self, allergy_id: str) -> dict:
    """
    Mark an allergy record as resolved.

    Args:
        allergy_id (str): Identifier of the allergy record to resolve.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "message": "Allergy record marked as resolved."
            }
        On failure, returns:
            {
                "success": False,
                "error": "<reason>"
            }

    Constraints:
        - The allergy record must exist.
        - Only the record status is modified; patient linkage and audit fields are preserved.
        - This operation does not validate clinician permissions because no actor context is provided by the environment.
    """
    if not isinstance(allergy_id, str) or not allergy_id.strip():
        return {"success": False, "error": "Invalid allergy_id"}

    record = self.allergy_records.get(allergy_id)
    if record is None:
        return {"success": False, "error": "Allergy record not found"}

    record["status"] = "resolved"
    self.allergy_records[allergy_id] = record

    return {"success": True, "message": "Allergy record marked as resolved."}

def verify_allergy_record(self, allergy_id: str, verified_by: str) -> dict:
    """
    Update the verification status for an allergy record after clinician review.

    Args:
        allergy_id (str): Identifier of the allergy record to verify.
        verified_by (str): Identifier of the clinician or user performing verification.

    Returns:
        dict: On success, {"success": True, "message": str}.
              On failure, {"success": False, "error": str}.

    Constraints:
        - The allergy record must exist.
        - The verification action must preserve audit fields such as recorded_at and recorded_by.
        - The verification reviewer identifier must be provided.
    """
    if not allergy_id:
        return {"success": False, "error": "allergy_id is required"}

    if not verified_by:
        return {"success": False, "error": "verified_by is required"}

    allergy_record = self.allergy_records.get(allergy_id)
    if allergy_record is None:
        return {"success": False, "error": "Allergy record not found"}

    allergy_record["verification_status"] = "verified"
    allergy_record["recorded_by"] = allergy_record.get("recorded_by", verified_by)

    return {
        "success": True,
        "message": f"Allergy record '{allergy_id}' marked as verified by '{verified_by}'."
    }

def link_allergy_to_patient(self, allergy_id: str, patient_id: str) -> dict:
    """
    Associate an existing allergy record with a valid patient.

    Args:
        allergy_id (str): Identifier of the allergy record to update.
        patient_id (str): Identifier of the patient to associate with the allergy record.

    Returns:
        dict: On success,
            { "success": True, "message": "Allergy record linked to patient successfully" }
        On failure,
            { "success": False, "error": "<reason>" }

    Constraints:
        - The allergy record must exist.
        - The patient must exist.
        - The allergy record must reference exactly one patient after the operation.
        - Audit fields such as recorded_at and recorded_by must not be modified.
    """
    if not allergy_id:
        return {"success": False, "error": "allergy_id is required"}
    if not patient_id:
        return {"success": False, "error": "patient_id is required"}

    allergy_record = self.allergy_records.get(allergy_id)
    if allergy_record is None:
        return {"success": False, "error": "Allergy record not found"}

    if patient_id not in self.patients:
        return {"success": False, "error": "Patient not found"}

    allergy_record["patient_id"] = patient_id
    self.allergy_records[allergy_id] = allergy_record

    return {"success": True, "message": "Allergy record linked to patient successfully"}

def correct_allergy_audit_fields(
    self,
    allergy_id: str,
    recorded_by: str | None = None,
    recorded_at: str | None = None,
) -> dict:
    """
    Amend audit metadata on an allergy record, such as recorded_by or recorded_at.

    Args:
        allergy_id (str): Identifier of the allergy record to update.
        recorded_by (str | None): Optional clinician/user identifier to replace the
            existing recorded_by value.
        recorded_at (str | None): Optional timestamp string to replace the existing
            recorded_at value.

    Returns:
        dict: On success, {"success": True, "message": "..."}.
              On failure, {"success": False, "error": "reason"}.

    Constraints:
        - The allergy record must exist.
        - Only audit metadata may be changed by this operation.
        - If recorded_by is provided, it must reference an existing clinician user.
        - If recorded_at is provided, it must be a non-empty string.
        - At least one audit field must be supplied.
    """
    allergy_record = self.allergy_records.get(allergy_id)
    if allergy_record is None:
        return {"success": False, "error": "Allergy record not found"}

    if recorded_by is None and recorded_at is None:
        return {"success": False, "error": "No audit fields provided for correction"}

    if recorded_by is not None:
        if not isinstance(recorded_by, str) or not recorded_by.strip():
            return {"success": False, "error": "Invalid recorded_by value"}
        if recorded_by not in self.clinician_users:
            return {"success": False, "error": "Recorded_by clinician not found"}
        allergy_record["recorded_by"] = recorded_by

    if recorded_at is not None:
        if not isinstance(recorded_at, str) or not recorded_at.strip():
            return {"success": False, "error": "Invalid recorded_at value"}
        allergy_record["recorded_at"] = recorded_at

    self.allergy_records[allergy_id] = allergy_record
    return {
        "success": True,
        "message": f"Allergy audit fields corrected for record {allergy_id}"
    }

