def create_allergy_record(self, allergy_record: dict) -> dict:
    """
    Add a new allergy record to the system.

    Args:
        allergy_record (dict): A dictionary containing the allergy record data.
            Required keys:
            - allergy_id
            - patient_id
            - allergen
            - reaction
            - severity
            - status
            - recorded_at
            - recorded_by
            - verification_status

    Returns:
        dict: On success, returns:
            {"success": True, "message": "Allergy record created successfully"}
        On failure, returns:
            {"success": False, "error": "<reason>"}

    Constraints:
        - allergy_id must be unique.
        - patient_id must reference an existing patient.
        - recorded_at, recorded_by, and verification_status are preserved as provided.
        - The method does not raise exceptions; invalid input is reported via the returned dict.
    """
    if not isinstance(allergy_record, dict):
        return {"success": False, "error": "Invalid allergy record payload"}

    required_fields = {
        "allergy_id",
        "patient_id",
        "allergen",
        "reaction",
        "severity",
        "status",
        "recorded_at",
        "recorded_by",
        "verification_status",
    }

    missing_fields = [field for field in required_fields if field not in allergy_record]
    if missing_fields:
        return {
            "success": False,
            "error": f"Missing required fields: {', '.join(sorted(missing_fields))}",
        }

    allergy_id = allergy_record.get("allergy_id")
    patient_id = allergy_record.get("patient_id")

    if not isinstance(allergy_id, str) or not allergy_id.strip():
        return {"success": False, "error": "Invalid allergy_id"}
    if not isinstance(patient_id, str) or not patient_id.strip():
        return {"success": False, "error": "Invalid patient_id"}

    if allergy_id in self.allergy_records:
        return {"success": False, "error": "Allergy record already exists"}

    if patient_id not in self.patients:
        return {"success": False, "error": "Patient does not exist"}

    self.allergy_records[allergy_id] = allergy_record  # preserve audit fields as provided
    return {"success": True, "message": "Allergy record created successfully"}

