def update_allergy_status(self, allergy_id: str, status: str) -> dict:
    """
    Update the status of an existing allergy record.

    Args:
        allergy_id (str): The unique identifier of the allergy record to update.
        status (str): The new status for the allergy record. Must be one of
            {"active", "inactive", "resolved"}.

    Returns:
        dict: On success, returns:
            {"success": True, "message": "..."}
        On failure, returns:
            {"success": False, "error": "..."}.

    Constraints:
        - The allergy record must exist.
        - The status must be one of: active, inactive, resolved.
        - This operation updates only the status field and preserves audit fields.
    """
    allowed_statuses = {"active", "inactive", "resolved"}

    if not isinstance(allergy_id, str) or not allergy_id.strip():
        return {"success": False, "error": "Invalid allergy_id"}

    if not isinstance(status, str) or not status.strip():
        return {"success": False, "error": "Invalid status"}

    normalized_status = status.strip().lower()
    if normalized_status not in allowed_statuses:
        return {
            "success": False,
            "error": "Invalid status; must be one of active, inactive, resolved"
        }

    record = self.allergy_records.get(allergy_id)
    if record is None:
        return {"success": False, "error": "Allergy record not found"}

    record["status"] = normalized_status
    self.allergy_records[allergy_id] = record

    return {
        "success": True,
        "message": f"Allergy record {allergy_id} status updated to {normalized_status}"
    }

